def walk(path):
    out = []
    for e in repo.list(path):
        p = path.rstrip("/") + "/" + e
        if e.endswith("/"):
            out.extend(walk(p))
        else:
            out.append(p)
    return out

src_files = walk("src/")
docs_files = walk("docs/")

contents = {}
for f in src_files + docs_files:
    c = repo.read(f, missing_ok=True)
    contents[f] = c if c != None else "<<BINARY/UNREADABLE>>"

result({
    "src_files": src_files,
    "docs_files": docs_files,
    "contents": contents,
})

